description\": \"第三幕：高潮+结局（20-30%篇幅）- X-Y化学反应爆发\",\n      \"required\": [\"description\", \"story_synopsis\", \"key_chapters\"],\n      \"properties\": {\n        \"description\": {\n          \"type\": \"string\",\n          \"description\": \"该幕的核心任务描述\"\n        },\n        \"story_synopsis\": {\n          \"type\": \"string\",\n          \"description\": \"本幕故事梗概（自然语言叙述，500-1000字）\",\n          \"minLength\": 500,\n          \"maxLength\": 1000\n        },\n        \"key_chapters\": {\n          \"type\": \"array\",\n          \"description\": \"该幕的关键章节数组\",\n          \"minItems\": 1,\n          \"items\": {\n            \"type\": \"object\",\n            \"required\": [\"chapter_number\", \"chapter_title\", \"chapter_synopsis\", \"scene_sequence\"],\n            \"properties\": {\n              \"chapter_number\": {\n                \"type\": \"integer\",\n                \"minimum\": 1,\n                \"description\": \"章节编号\"\n              },\n              \"chapter_title\": {\n                \"type\": \"string\",\n                \"description\": \"章节标题\"\n              },\n              \"chapter_synopsis\": {\n                \"type\": \"string\",\n                \"description\": \"本章故事梗概（自然语言叙述，200-400字）\",\n                \"minLength\": 200,\n                \"maxLength\": 400\n              },\n              \"scene_sequence\": {\n                \"type\": \"array\",\n                \"description\": \"本章场景序列（至少3个场景）\",\n                \"minItems\": 3,\n                \"items\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"scene_number\",\n                    \"scene_location\",\n                    \"characters_present\",\n                    \"scene_purpose\",\n                    \"core_action\",\n                    \"conflict_point\",\n                    \"emotional_shift\",\n                    \"scene_outcome\"\n                  ],\n                  \"properties\": {\n          